    (0, [])
    >>> filter_by_substring(['abc', 'bacd', 'cde', 'array'], 'a')
    (3, ['abc', 'bacd', 'array'])
    """
    def contains_substring(s: str, sub: str) -> bool:
        # Case insensitive check only for 'a' and 'A', but case sensitive otherwise
        # So treat 'a' and 'A' as equal but all other chars case sensitive.
        # We'll do a custom approach:
        # For substring, replace 'a' with '[aA]' to match either 'a' or 'A'
        # But we cannot use regex or loops, so instead we can check for substring presence by
        # scanning s for substring with special 'a'/'A' logic recursively

        # To avoid loops/comprehensions, we use recursion.
        def match_at(i: int, j: int) -> bool:
            if j == len(sub):
                return True
            if i == len(s):
                return False
            sc = s[i]
            jc = sub[j]
            # compare characters with 'a' and 'A' treated equal
            if (jc == 'a' or jc == 'A') and (sc == 'a' or sc == 'A'):
                return match_at(i + 1, j + 1)
            if sc == jc:
                return match_at(i + 1, j + 1)
            return False

        def search(i: int) -> bool:
            if i + len(sub) > len(s):
                return False
            if match_at(i, 0):
                return True
            return search(i + 1)

        return search(0)

    def filter_recursive(lst: List[str]) -> List[str]:
        if not lst:
            return []
        head, *tail = lst
        rest = filter_recursive(tail)
        if contains_substring(head, substring):
            return [head] + rest
        else:
            return rest

    filtered = filter_recursive(strings)
    # maintain original order (already) and then sort alphabetically
    sorted_filtered = sorted(filtered)
    return len(sorted_filtered), sorted_filtered

