    """Return the string "prime" if a given number is prime, and string "not prime" otherwise.
    Accepts string inputs representing integers.
    """
    if isinstance(n, str):
        if not n.isdigit():
            return "not prime"  # Non-digit strings are not prime numbers
        n = int(n)
    elif not isinstance(n, int):
        return "not prime"

    if n <= 1:
        return "not prime"
    if n <= 3:
        return "prime"
    if n % 2 == 0 or n % 3 == 0:
        return "not prime"
    i = 5
    while i * i <= n:
