    for i in range(n):
        dp[i][i] = 1

    # Fill dp for substrings of length 2 to n
    for length in range(2, n+1):
        for i in range(n-length+1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = 2 + (dp[i+1][j-1] if i+1 <= j-1 else 0)
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    # Reconstruct the shortest palindromic sequence that is longest palindromic subsequence
    i, j = 0, n-1
    left_part = []
    right_part = []

    while i <= j:
        if s[i] == s[j]:
            left_part.append(s[i])
            if i != j:
                right_part.append(s[j])
            i += 1
            j -= 1
        elif dp[i+1][j] >= dp[i][j-1]:
            i += 1
        else:
            j -= 1

